import{_ as t,o as a,c as r,a3 as s}from"./chunks/framework.CpLciM8b.js";const f=JSON.parse('{"title":"Your first insight","description":"","frontmatter":{},"headers":[],"relativePath":"guide/first-insight.md","filePath":"guide/first-insight.md","lastUpdated":1785497735000}'),o={name:"guide/first-insight.md"};function n(i,e,h,l,u,d){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="your-first-insight" tabindex="-1">Your first insight <a class="header-anchor" href="#your-first-insight" aria-label="Permalink to &quot;Your first insight&quot;">​</a></h1><p>Once a few runs have landed, the dashboard turns them into answers. Here is the path from raw runs to a decision.</p><h2 id="_1-the-flaky-board" tabindex="-1">1. The flaky board <a class="header-anchor" href="#_1-the-flaky-board" aria-label="Permalink to &quot;1. The flaky board&quot;">​</a></h2><p>The flaky board ranks every test by its flaky score, worst first. The score is a Beta-Binomial estimate with exponential time-decay — recent behaviour counts for more than last month&#39;s. A test only appears once it has enough samples to be meaningful, so a single red run does not brand a test as flaky.</p><h2 id="_2-reason-codes" tabindex="-1">2. Reason codes <a class="header-anchor" href="#_2-reason-codes" aria-label="Permalink to &quot;2. Reason codes&quot;">​</a></h2><p>Open a test and the score breaks into <strong>reason codes</strong> — the human-readable evidence behind the number:</p><ul><li><strong>same commit, different result</strong> — the strongest flaky signal: the code did not change but the outcome did.</li><li><strong>pass-on-rerun</strong> — failed, then passed on retry with no code change.</li><li><strong>intermittent across branches</strong> — fails on some branches and not others without a code reason.</li></ul><p>Because every score ships with its reasons, you can trust it — or argue with it — instead of taking a black-box number on faith. See <a href="/flakemetry/v/2026-09-30/concepts/flaky-scoring">Flaky scoring</a> for the model.</p><h2 id="_3-test-history-that-survives-refactors" tabindex="-1">3. Test history that survives refactors <a class="header-anchor" href="#_3-test-history-that-survives-refactors" aria-label="Permalink to &quot;3. Test history that survives refactors&quot;">​</a></h2><p>A test&#39;s history does not reset when you move or rename its file. The <a href="/flakemetry/v/2026-09-30/concepts/test-identity">test identity engine</a> stitches executions across refactors, so the flaky score reflects the test&#39;s real long-run behaviour rather than the age of its current file path.</p><h2 id="_4-root-cause-on-failures" tabindex="-1">4. Root-cause on failures <a class="header-anchor" href="#_4-root-cause-on-failures" aria-label="Permalink to &quot;4. Root-cause on failures&quot;">​</a></h2><p>For genuinely new failure signatures, the <a href="/flakemetry/v/2026-09-30/concepts/ai-rca">AI RCA</a> panel offers a structured &quot;likely cause + suggested action&quot;. Failures are normalized and clustered first, so only new signatures reach the model — root-cause without a per-failure LLM bill.</p><h2 id="_5-guard-your-pull-requests" tabindex="-1">5. Guard your pull requests <a class="header-anchor" href="#_5-guard-your-pull-requests" aria-label="Permalink to &quot;5. Guard your pull requests&quot;">​</a></h2><p>Wire the <a href="/flakemetry/v/2026-09-30/guide/github-action">GitHub Action</a> in and every PR gets a sticky comment plus a quality gate that distinguishes <em>new</em> failures this change introduced from tests that already flake on the base branch — blocking only what the change actually broke.</p><h2 id="_6-track-the-trend" tabindex="-1">6. Track the trend <a class="header-anchor" href="#_6-track-the-trend" aria-label="Permalink to &quot;6. Track the trend&quot;">​</a></h2><p>The <strong>Test health</strong> page answers the executive question: is flakiness improving or degrading? It reports <strong>flaky MTTR</strong> (how long a test stays flaky before it stabilizes), <strong>flaky-introduced vs -resolved per week</strong>, the current <strong>quarantine backlog</strong>, and the overall reliability trend — over a time range up to a quarter. A net-positive week (more introduced than resolved) is the early warning that flakiness is winning.</p>',16)])])}const g=t(o,[["render",n]]);export{f as __pageData,g as default};
